3	import org.springframework.samples.petclinic.mapper.LocalityLookup;
4	import org.springframework.samples.petclinic.model.Owner;
5	
6	/**
7	 * The REGION segment of an owner's region-and-hash identity (see {@link AssignCustomerCode}). It is
8	 * the prefix of an already-assigned {@code customerCode} (the part before the {@code '-'} separating
9	 * it from the hash), otherwise the region derived from the owner's postcode with the city as a
10	 * fallback (see {@link LocalityLookup#regionOf(String, String)}). Deriving the read-time locality from
11	 * this is how the locality moves onto the region-and-hash identity.
12	 */
13	public final class CustomerCodeRegion {
14	
15	    private CustomerCodeRegion() {
16	    }
17	
18	    /** The REGION segment for {@code owner}. */
19	    public static String of(Owner owner) {
20	        String code = owner.getCustomerCode();
21	        if (code != null) {
22	            int dash = code.indexOf('-');
23	            if (dash > 0) {
24	                return code.substring(0, dash);
25	            }
26	        }
27	        return LocalityLookup.regionOf(owner.getCity(), owner.getPostcode());
28	    }
29	}
