1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.model.Owner;
4	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
5	
6	/**
7	 * The owner's {@code identityKey}: the full lower-case hex SHA-256 (64 characters) over
8	 * {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. It is the single basis of
9	 * the duplicate check — {@link EnsureUniqueIdentity} rejects a create whose key collides with an
10	 * existing non-deleted owner's key (409) — and is also surfaced on the owner response.
11	 *
12	 * <ul>
13	 * <li><b>normalizedTelephone</b> — the E.164 form (see {@link E164Telephone}); the stored telephone
14	 * is already E.164 and re-normalizing is idempotent. An unparseable/absent telephone contributes an
15	 * empty segment.</li>
16	 * <li><b>lowerEmail</b> — the trimmed, lower-cased address, or empty when the owner has none.</li>
17	 * <li><b>soundex(lastName)</b> — the {@link Soundex} code of the last name, so sound-alike surnames
18	 * share this segment.</li>
19	 * </ul>
20	 */
21	public final class OwnerIdentityKey {
22	
23	    private OwnerIdentityKey() {
24	    }
25	
26	    /** The identity key of an already-built/stored owner, for the response and the duplicate check. */
27	    public static String of(Owner owner) {
28	        return build(owner.getTelephone(), owner.getEmail(), owner.getLastName());
29	    }
30	
31	    /** The identity key a create request would receive, for the duplicate check before the owner exists. */
32	    static String of(OwnerFieldsDto request) {
33	        return build(request.getTelephone(), request.getEmail(), request.getLastName());
34	    }
35	
36	    /** The identity key from raw parts: SHA-256 hex over the normalized telephone, email and soundex. */
37	    static String build(String telephone, String email, String lastName) {
38	        String tel = E164Telephone.toE164OrNull(telephone);
39	        String source = (tel == null ? "" : tel) + "|"
40	                + (email == null ? "" : email.trim().toLowerCase()) + "|"
41	                + Soundex.of(lastName);
42	        return Sha256Hex.of(source);
43	    }
44	}
