6	/**
7	 * Assigns the owner's {@code membershipNumber}, formatted {@code <customerCode>-M<YY>}
8	 * where YY is the last two digits of the fiscal year (1 July basis) of the business-day-adjusted
9	 * {@code registrationDate} (e.g. {@code NSW-1A2B3C4D-M27}). Runs after the customer code and
10	 * registration date have been assigned.
11	 */
12	public class AssignMembershipNumber {
13	
14	    public void service(@Val Owner owner) {
15	        String yy = String.format("%02d", FiscalYear.endingYear(owner.getRegistrationDate()) % 100);
16	        owner.setMembershipNumber(owner.getCustomerCode() + "-M" + yy);
17	    }
18	}
