1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import java.time.LocalDate;
4	import java.time.Month;
5	
6	/**
7	 * Fiscal-year helpers on a 1 July basis. The fiscal year runs 1 July to 30 June and is labelled by
8	 * the calendar year in which it ends: a date on or after 1 July belongs to the fiscal year ending
9	 * the following calendar year (e.g. {@code 2026-09-04 -> FY27}), while a date before 1 July belongs
10	 * to the fiscal year ending in its own calendar year (e.g. {@code 2026-03-01 -> FY26}). Every
11	 * date-derived value keyed on the (business-day adjusted) registration date uses this basis.
12	 */
13	public final class FiscalYear {
14	
15	    private FiscalYear() {
16	    }
17	
18	    /** The calendar year in which the fiscal year containing {@code date} ends. */
19	    public static int endingYear(LocalDate date) {
20	        return date.getMonthValue() >= Month.JULY.getValue() ? date.getYear() + 1 : date.getYear();
21	    }
22	
23	    /** The {@code FY<YY>} label for the fiscal year containing {@code date}, or {@code null} when
24	     *  {@code date} is {@code null}. YY is the last two digits of the fiscal year's ending year. */
25	    public static String label(LocalDate date) {
26	        if (date == null) {
27	            return null;
28	        }
29	        return String.format("FY%02d", endingYear(date) % 100);
30	    }
31	
32	    /** The number of whole fiscal years elapsed between {@code from} and {@code to} — the count of
33	     *  1 July boundaries crossed. */
34	    public static long elapsedBetween(LocalDate from, LocalDate to) {
35	        return (long) endingYear(to) - endingYear(from);
36	    }
37	}
