1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import net.officefloor.plugin.variable.Val;
4	import org.springframework.samples.petclinic.model.Owner;
5	import org.springframework.samples.petclinic.repository.OwnerRepository;
6	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
7	import org.springframework.samples.petclinic.rest.escalation.DuplicateOwnerException;
8	
9	/**
10	 * The duplicate check for creating owners, keyed on the single {@link OwnerIdentityKey} —
11	 * SHA-256 over {@code normalizedTelephone + '|' + lowerEmail + '|' + soundex(lastName)}. A create is
12	 * rejected with 409 via {@link DuplicateOwnerException} when its identity key equals that of an
13	 * existing non-deleted owner: the same person (same telephone, email and sound-alike last name).
14	 *
15	 * <p>Because the telephone is part of the key, two owners with the same last name and postcode but
16	 * different telephones are no longer a hard household duplicate here — they are created and flagged a
17	 * soft match by {@link AssignPossibleDuplicate} instead. The email-domain blocklist runs earlier in the
18	 * pipeline ({@link ValidateOwnerEmailDomain}), so a blocked email is a 400 before this check. Setting
19	 * {@code sharesHousehold} true bypasses this block (and, being declared, the owner is not flagged as a
20	 * possible duplicate). Runs before {@link BuildOwner}.
21	 */
22	public class EnsureUniqueIdentity {
23	
24	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
25	            throws DuplicateOwnerException {
26	        if (Boolean.TRUE.equals(request.getSharesHousehold())) {
27	            return; // declared household member — bypass the duplicate block
28	        }
29	        String identityKey = OwnerIdentityKey.of(request);
30	        for (Owner existing : ownerRepository.findAll()) {
31	            if (existing.isDeleted()) {
32	                continue; // a soft-deleted owner no longer blocks a duplicate
33	            }
34	            if (identityKey.equals(OwnerIdentityKey.of(existing))) {
35	                throw new DuplicateOwnerException(identityKey);
36	            }
37	        }
38	    }
39	}
