3	import java.util.Set;
4	
5	import org.springframework.samples.petclinic.model.Owner;
6	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
7	
8	/**
9	 * The owner's marketing segment, formatted '&lt;TIER&gt;_&lt;AREA&gt;' — one of 'PREMIUM_METRO',
10	 * 'PREMIUM_REGIONAL', 'STANDARD_METRO' or 'STANDARD_REGIONAL'. TIER is 'PREMIUM' when the owner's
11	 * {@code membershipLevel} is 3 or more, otherwise 'STANDARD'. AREA is 'METRO' when the owner's
12	 * locality (see {@link CustomerCodeRegion#of(Owner)}) is a known region (NSW, VIC or QLD),
13	 * otherwise 'REGIONAL'.
14	 */
15	public final class OwnerSegment {
16	
17	    /** The known metropolitan regions. */
18	    private static final Set<String> METRO_REGIONS = Set.of("NSW", "VIC", "QLD");
19	
20	    private OwnerSegment() {
21	    }
22	
23	    /** The '&lt;TIER&gt;_&lt;AREA&gt;' segment for {@code owner}. */
24	    public static OwnerDto.OwnerSegmentEnum of(Owner owner) {
25	        Integer level = owner.getMembershipLevel();
26	        boolean premium = level != null && level >= 3;
27	        boolean metro = METRO_REGIONS.contains(CustomerCodeRegion.of(owner));
28	        if (premium) {
29	            return metro ? OwnerDto.OwnerSegmentEnum.PREMIUM_METRO : OwnerDto.OwnerSegmentEnum.PREMIUM_REGIONAL;
30	        }
31	        return metro ? OwnerDto.OwnerSegmentEnum.STANDARD_METRO : OwnerDto.OwnerSegmentEnum.STANDARD_REGIONAL;
32	    }
33	}
