5	import org.slf4j.Logger;
6	import org.slf4j.LoggerFactory;
7	
8	import net.officefloor.plugin.variable.Val;
9	import org.springframework.samples.petclinic.model.Owner;
10	
11	import tools.jackson.databind.ObjectMapper;
12	
13	/**
14	 * Emits, on successful create, two things via the dedicated {@code AUDIT} logger:
15	 * <ol>
16	 * <li>the human-readable audit line, carrying the newly assigned owner id together
17	 * with its {@code customerCode}, {@code registrationDate}, {@code membershipLevel} and
18	 * {@code membershipNumber}; and</li>
19	 * <li>an immutable structured event —
20	 * {@code {seq, ownerId, customerCode, membershipLevel, event:'OWNER_CREATED'}} — where
21	 * {@code seq} is a monotonically increasing integer across creates.</li>
22	 * </ol>
23	 * Runs after the owner has been saved so the id is set.
24	 */
25	public class AuditOwnerCreated {
26	
27	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
28	
29	    private static final ObjectMapper JSON = new ObjectMapper();
30	
31	    /** Monotonically increasing sequence number, shared across all creates in the JVM. */
32	    private static final AtomicLong SEQ = new AtomicLong();
33	
34	    public void service(@Val Owner owner) {
35	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
36	                owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
37	                owner.getMembershipLevel(), owner.getMembershipNumber());
38	
39	        OwnerCreatedEvent event = new OwnerCreatedEvent(SEQ.incrementAndGet(), owner.getId(),
40	                primaryIdentifier(owner), owner.getMembershipLevel());
41	        AUDIT.info(JSON.writeValueAsString(event));
42	    }
43	
44	    /**
45	     * The owner's current primary identifier. Today that is the {@code customerCode};
46	     * when the customerCode is later unified into the {@code memberId}, this is the single
47	     * place to switch so the event carries the memberId instead.
48	     */
49	    private static String primaryIdentifier(Owner owner) {
50	        return owner.getCustomerCode();
51	    }
52	
53	    /**
54	     * Immutable structured audit event for a created owner. Field order matches the
55	     * documented shape {@code {seq, ownerId, customerCode, membershipLevel, event}}; the
56	     * {@code event} marker is fixed at {@code OWNER_CREATED}.
57	     */
58	    public record OwnerCreatedEvent(long seq, Integer ownerId, String customerCode, Integer membershipLevel,
59	            String event) {
60	        public OwnerCreatedEvent(long seq, Integer ownerId, String customerCode, Integer membershipLevel) {
61	            this(seq, ownerId, customerCode, membershipLevel, "OWNER_CREATED");
62	        }
63	    }
64	}
