1	package org.springframework.samples.petclinic.rest.function.owner;
2	
3	import org.springframework.samples.petclinic.rest.escalation.InvalidTelephoneException;
4	
5	/**
6	 * Converts a raw telephone into E.164 form. Spaces, dashes and brackets are stripped. A leading
7	 * '+' with its country code is kept; otherwise country code '+61' is assumed and a single leading
8	 * '0' is dropped from the national digits. The result must carry 8 to 15 digits after the '+',
9	 * else it is rejected with {@link InvalidTelephoneException} (a 400). So {@code '0412 345 678'}
10	 * becomes {@code '+61412345678'} and {@code '+64 21 123 456'} becomes {@code '+6421123456'}.
11	 *
12	 * <p>The national-number length is additionally checked against known country codes: {@code '+61'}
13	 * requires exactly 9 national digits and {@code '+1'} requires exactly 10. A number whose national
14	 * length is wrong for its country is rejected with {@link InvalidTelephoneException} (a 400). Other
15	 * country codes are only bound by the general 8-to-15 total-digit rule.
16	 */
17	final class E164Telephone {
18	
19	    private E164Telephone() {
20	    }
21	
22	    /** Normalize to E.164, throwing when the value cannot form a valid number. */
23	    static String toE164(String raw) throws InvalidTelephoneException {
24	        String cleaned = raw == null ? "" : raw.replaceAll("[\\s()\\-]", "");
25	        String digits;
26	        if (cleaned.startsWith("+")) {
27	            digits = cleaned.substring(1);
28	        }
29	        else {
30	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
31	            digits = "61" + national;
32	        }
33	        if (!digits.matches("\\d{8,15}")) {
34	            throw new InvalidTelephoneException(raw);
35	        }
36	        // National-number length must match the country code.
37	        if (digits.startsWith("61")) {
38	            if (digits.length() - 2 != 9) {
39	                throw new InvalidTelephoneException(raw);
40	            }
41	        }
42	        else if (digits.startsWith("1")) {
43	            if (digits.length() - 1 != 10) {
44	                throw new InvalidTelephoneException(raw);
45	            }
46	        }
47	        return "+" + digits;
48	    }
49	
50	    /** Normalize to E.164, or {@code null} when the value cannot form a valid number. */
51	    static String toE164OrNull(String raw) {
52	        try {
53	            return toE164(raw);
54	        }
55	        catch (InvalidTelephoneException ex) {
56	            return null;
57	        }
58	    }
59	}
